def fibfib(n: int) -> int:
    if n <= 0:
        return 0
    if n == 1:
        return 0
    # Use simple recursion with memoization to improve performance
    memo = {0: 0, 1: 0}
    def helper(k: int) -> int:
        if k in memo:
            return memo[k]
        memo[k] = helper(k - 1) + helper(k - 2)
        return memo[k]
    return helper(n)
